LostWaxMolderMaker.ironStock = 12; LostWaxMolderMaker.bronzeStock = 10; LostWaxMolderMaker.woodStock = 16; LostWaxMolderMaker.leatherStock = 12; LostWaxMolderMaker.silverStock = 8; LostWaxMolderMaker.goldStock = 6; LostWaxMolderMaker.jewelStock = 4; LostWaxMolderMaker.pearlStock = 4
LostWaxMolderMaker.productStock = {}; LostWaxMolderMaker.buildings = {}; LostWaxMolderMaker.maker = nil; LostWaxMolderMaker.activeMaking = {}; LostWaxMolderMaker.totalProducts = 0; LostWaxMolderMaker.dayTimer = 0
function LostWaxMolderMaker.init() LostWaxMolderMaker.ironStock=12; LostWaxMolderMaker.bronzeStock=10; LostWaxMolderMaker.woodStock=16; LostWaxMolderMaker.leatherStock=12; LostWaxMolderMaker.silverStock=8; LostWaxMolderMaker.goldStock=6; LostWaxMolderMaker.jewelStock=4; LostWaxMolderMaker.pearlStock=4; LostWaxMolderMaker.productStock={}; LostWaxMolderMaker.buildings={}; LostWaxMolderMaker.maker=nil; LostWaxMolderMaker.activeMaking={}; LostWaxMolderMaker.totalProducts=0; LostWaxMolderMaker.dayTimer=0; print("[LostWaxMolderMaker] Royal Lost Wax Molder Maker System initialized (6 products, 4 buildings)") end
function LostWaxMolderMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; LostWaxMolderMaker.maker={name=n or ("Voscar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Voscar najet: %s (spretnost: %d)",LostWaxMolderMaker.maker.name,s),"success") end; return true end
function LostWaxMolderMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function LostWaxMolderMaker.build(id) local ok,e=LostWaxMolderMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(LostWaxMolderMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function LostWaxMolderMaker.getQualityBonus() local b=0; for _,bd in ipairs(LostWaxMolderMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function LostWaxMolderMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and LostWaxMolderMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and LostWaxMolderMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and LostWaxMolderMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and LostWaxMolderMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and LostWaxMolderMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and LostWaxMolderMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and LostWaxMolderMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and LostWaxMolderMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #LostWaxMolderMaker.buildings==0 then return false,"Potrebna vosarska delavnica" end; if not LostWaxMolderMaker.maker then return false,"Potreben voscar" end; return true end
function LostWaxMolderMaker.make(pt,qty) qty=qty or 1; local ok,e=LostWaxMolderMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then LostWaxMolderMaker.ironStock=LostWaxMolderMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then LostWaxMolderMaker.bronzeStock=LostWaxMolderMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then LostWaxMolderMaker.woodStock=LostWaxMolderMaker.woodStock-d.woodCost*qty end; if d.leatherCost then LostWaxMolderMaker.leatherStock=LostWaxMolderMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then LostWaxMolderMaker.silverStock=LostWaxMolderMaker.silverStock-d.silverCost*qty end; if d.goldCost then LostWaxMolderMaker.goldStock=LostWaxMolderMaker.goldStock-d.goldCost*qty end; if d.jewelCost then LostWaxMolderMaker.jewelStock=LostWaxMolderMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then LostWaxMolderMaker.pearlStock=LostWaxMolderMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if LostWaxMolderMaker.maker then t=math.max(1,t-math.floor(LostWaxMolderMaker.maker.skill/13)) end; table.insert(LostWaxMolderMaker.activeMaking,{id="lostwaxmolder_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function LostWaxMolderMaker.completeMaking(m) local q=1.0+(LostWaxMolderMaker.getQualityBonus()/100); if LostWaxMolderMaker.maker then q=q+(LostWaxMolderMaker.maker.skill/140) end; q=math.min(2.5,q); LostWaxMolderMaker.productStock[m.productType]=(LostWaxMolderMaker.productStock[m.productType] or 0)+m.quantity; LostWaxMolderMaker.totalProducts=LostWaxMolderMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if LostWaxMolderMaker.maker then LostWaxMolderMaker.maker.itemsMade=LostWaxMolderMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then LostWaxMolderMaker.maker.skill=math.min(100,LostWaxMolderMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Model izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"lostwaxmolder.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function LostWaxMolderMaker.update(dt) if not _G.state then return end; LostWaxMolderMaker.dayTimer=LostWaxMolderMaker.dayTimer+dt; if LostWaxMolderMaker.dayTimer>=30 then LostWaxMolderMaker.dayTimer=0; for i=#LostWaxMolderMaker.activeMaking,1,-1 do local m=LostWaxMolderMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then LostWaxMolderMaker.completeMaking(m); table.remove(LostWaxMolderMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(LostWaxMolderMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if LostWaxMolderMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function LostWaxMolderMaker.getStats() return {ironStock=LostWaxMolderMaker.ironStock,bronzeStock=LostWaxMolderMaker.bronzeStock,woodStock=LostWaxMolderMaker.woodStock,leatherStock=LostWaxMolderMaker.leatherStock,silverStock=LostWaxMolderMaker.silverStock,goldStock=LostWaxMolderMaker.goldStock,jewelStock=LostWaxMolderMaker.jewelStock,pearlStock=LostWaxMolderMaker.pearlStock,productStock=LostWaxMolderMaker.productStock,numBuildings=#LostWaxMolderMaker.buildings,hasMaker=LostWaxMolderMaker.maker~=nil,makerName=LostWaxMolderMaker.maker and LostWaxMolderMaker.maker.name or "—",makerSkill=LostWaxMolderMaker.maker and LostWaxMolderMaker.maker.skill or 0,activeMaking=#LostWaxMolderMaker.activeMaking,totalProducts=LostWaxMolderMaker.totalProducts} end
return LostWaxMolderMaker
